import {trophyPoster} from './trophy-poster.js';
const J=globalThis.window?.jarvis;
if(J&&(new URLSearchParams(location.search).get('view')||'main')==='main'){
  const api=(method,data={})=>J.call('core',{method,data}),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let panel,state,tab='proposals',draft=null,answer=null,busy=false,previous,masked=false,opening=false,posterChain=Promise.resolve();
  const say=t=>{if(panel)panel.querySelector('[role=status]').textContent=t;},field=(label,name,value='',type='text')=>`<label>${label}<input name="${name}" type="${type}" ${type==='number'?'min="0" max="10" step="0.05"':''} value="${esc(value)}"></label>`,area=(label,name,value='',rows=5)=>`<label>${label}<textarea name="${name}" rows="${rows}">${esc(value)}</textarea></label>`;
  async function close(){if(busy||opening)return;panel?.remove();panel=null;if(masked)await J.call('tabs-show',true).catch(()=>{});masked=false;window.__jarvisHolo?.pauseAll(false);previous?.focus?.();}
  async function show(which='proposals'){if(busy||opening)return;opening=true;try{state=await api('work-desk');if(!panel){previous=document.activeElement;masked=await J.call('tabs-state').catch(()=>false);if(masked)await J.call('tabs-show',false);window.__jarvisHolo?.pauseAll(true);}panel?.remove();panel=document.createElement('section');panel.className='wb-panel wd-panel';panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label','Work desk');panel.innerHTML='<header><div><small>JARVIS / WORK WORTH KEEPING</small><h2>Work desk</h2></div><button data-act="close">Close</button></header><div class="wb-body"><nav class="wb-filters"></nav><main></main></div><p class="wb-status" role="status"></p>';document.body.append(panel);panel.onclick=e=>{const b=e.target.closest('[data-act]');if(b)run(b.dataset.act,b).catch(e=>say(e.message));};panel.onsubmit=e=>{e.preventDefault();submit(e.target).catch(e=>say(e.message));};tab=which;draw();panel.querySelector('button').focus();}catch(e){if(masked)await J.call('tabs-show',true).catch(()=>{});masked=false;window.__jarvisHolo?.pauseAll(false);alert('Work desk could not open: '+e.message);}finally{opening=false;}}
  function draw(){if(!panel)return;panel.querySelector('nav').innerHTML=[['proposals','Proposals & quotes'],['files','Ask your files'],['trophies','Trophy wall'],['photos','Photo drop'],['brand','Branding & voices']].map(([k,v])=>`<button data-act="tab" data-tab="${k}" aria-pressed="${tab===k}">${v}</button>`).join('');const box=panel.querySelector('main');box.innerHTML=state.error?`<p>${esc(state.error)}</p>`:'';
    if(tab==='brand')box.innerHTML+=`<form data-form="brand"><h3>Your business identity</h3>${field('Business name','name',state.brand.name)}${field('Tagline','tagline',state.brand.tagline)}${area('Business contact details','contact',state.brand.contact,3)}${field('Brand colour','colour',state.brand.colour,'color')}${state.brand.logo?`<img class="wd-logo" alt="Saved business logo" src="${esc(state.brand.logo)}">`:''}<p><button type="button" data-act="logo">Choose logo</button></p><button class="wb-primary">Save branding</button></form><hr><form data-form="voices"><h3>Assistant personalities</h3><p>JARVIS: dry and precise. Alfred: formal and caring. Karen: upbeat and encouraging. Existing installed voice choices and your volume controls remain in use; this does not clone an actor’s voice.</p><label><input type="checkbox" name="personalities" ${state.config.personalities?'checked':''}> Use each hall’s personality in conversation</label><p>WhatsApp and phone calls remain JARVIS. Chat in a hall to hear its assistant.</p><button>Save voice preference</button></form>`;
    if(tab==='proposals'){box.innerHTML+=`<p>Give JARVIS the facts. Review the draft, prices, dates and terms before sharing. ${!state.brand.name?'Save a business name in Branding first.':''}</p>`;
      if(!draft)box.innerHTML+=`<form data-form="proposal"><div class="wb-grid">${field('Project title','title')}${field('Client','client')}</div><label>Document type<select name="kind"><option value="proposal">Proposal</option><option value="quote">Quote</option></select></label>${area('Your bullet points','bullets','',6)}${area('Quote items: Description | Quantity | Unit price','items','',3)}<div class="wb-grid">${field('Currency code','currency','GBP')}${field('Tax and payment facts (optional)','tax')}</div><p>Missing prices remain “To confirm”. Generating uses your configured Claude key and daily budget.</p><button class="wb-primary">Prepare draft</button></form><h3>Saved drafts</h3>${state.proposals.map(p=>`<article class="wb-item"><h3>${esc(p.title)}</h3><p>${esc(p.client)} · ${new Date(p.createdAt).toLocaleDateString('en-GB')} · draft</p><button data-act="edit" data-id="${p.id}">Review draft</button></article>`).join('')||'<p>No drafts yet.</p>'}`;
      else box.innerHTML+=`<form data-form="edit" data-id="${draft.id}">${field('Project title','title',draft.title)}${field('Client','client',draft.client)}${Object.entries(draft.sections).map(([k,v])=>area(k,'section:'+k,v)).join('')}${draft.kind==='quote'?area('Quote items: Description | Quantity | Unit price','items',draft.items,4)+field('Tax and payment facts','tax',draft.tax):''}<button class="wb-primary">Save reviewed draft</button><button type="button" data-act="export" data-id="${draft.id}">Save and export PDF</button><button type="button" data-act="draft-close">Back to drafts</button></form>`;
    }
    if(tab==='files')box.innerHTML+=`<h3>Ask your documents</h3><p>Folder: ${esc(state.folder)}</p><button data-act="folder">Choose folder</button><p>Searches PDF, Word DOCX, TXT, Markdown and CSV locally. Matching excerpts are sent to your configured Claude API to answer. Scanned PDFs need an OCR text copy. Searches have limits; unreadable or skipped files are reported.</p><form data-form="files">${field('Question','question',answer?.question||'')}<button class="wb-primary">Find a sourced answer</button></form>${answer?`<article class="wb-item"><p class="wd-pre">${esc(answer.answer)}</p><p>Read ${answer.scanned} of ${answer.total} supported documents.</p></article>${(answer.citations?.length?answer.citations:answer.sources).map(s=>`<article class="wb-item"><h3>${esc(s.name)} · ${esc(s.location)}</h3><blockquote>${esc(s.quote||s.excerpt)}</blockquote><button data-act="source" data-id="${s.id}">Open source document</button></article>`).join('')}${answer.warnings.length?`<details><summary>Search coverage and warnings</summary><p>${answer.warnings.map(esc).join('<br>')}</p></details>`:''}`:''}`;
    if(tab==='trophies'){box.innerHTML+=`<p>Keep a dated suit display for work you have accepted. Retiring a project preserves its finished result; the working suit remains available for your next project.</p><form data-form="trophy"><label>Accepted project<select name="runId" required>${state.eligible.map(r=>`<option value="${r.id}">${esc(r.title)}</option>`).join('')||'<option value="">Accept a finished Tower result first</option>'}</select></label><label>Suit for the display<select name="suit" required>${state.suits.map(s=>`<option value="${s.theme}:${s.id}">${esc(s.hall)} · ${esc(s.name)}</option>`).join('')}</select></label>${area('Portfolio description','description','',3)}<button class="wb-primary" ${state.eligible.length?'':'disabled'}>Retire project to wall</button></form><p><button data-act="portfolio">Export portfolio page</button></p><div class="wd-wall">${state.trophies.map(t=>`<article class="wd-trophy"><div class="wd-case"><img data-poster="${t.id}" alt="${esc(t.suitName)} trophy suit"></div><small>RETIRED · ${new Date(t.completedAt).toLocaleDateString('en-GB')}</small><h3>${esc(t.title)}</h3><p>${esc(t.suitName)}</p><p>${esc(t.description)}</p><button data-act="result" data-id="${t.id}">Open finished work</button><button data-act="restore" data-id="${t.id}">Remove from wall</button></article>`).join('')||'<p>Your first accepted project will earn its place here.</p>'}</div>`;
      for(const t of state.trophies.slice(0,12)){const img=box.querySelector(`[data-poster="${t.id}"]`);posterChain=posterChain.catch(()=>{}).then(()=>img.isConnected?trophyPoster(J,t,img):null).catch(()=>{if(img.isConnected)img.alt=t.suitName+' · model preview unavailable';});}
    }
    if(tab==='photos')box.innerHTML+=`${state.photoError?`<p>${esc(state.photoError)}</p>`:''}<h3>Receipt, whiteboard or business card</h3><p>Send one JPEG or PNG on WhatsApp, or choose a photo here. Originals stay in Documents → JARVIS → Photo inbox. Readable photos file under Expenses, Whiteboards or Contacts. Check extracted details; nothing is sent to a contact or booked as a payment.</p><form data-form="photos"><label><input type="checkbox" name="photoDrop" ${state.config.photoDrop?'checked':''}> Receive my WhatsApp photos</label><label><input type="checkbox" name="photoAnalysis" ${state.config.photoAnalysis?'checked':''}> Send these photos to Claude for paid reading</label>${field('Daily photo allowance (US dollars)','photoLimit',state.config.photoLimit,'number')}<p>Each reading reserves US$0.05 before upload, including uncertain failures. Your provider bill may be lower. No automatic paid retries. Up to 4 MB per photo.</p><button>Save photo preferences</button></form><button data-act="photo-import">Choose photo</button>${state.photos.map(x=>`<article class="wb-item"><h3>${esc(x.details?.kind||'Photo')} · ${x.reviewed?'reviewed':esc(x.status)}</h3><p>${new Date(x.at).toLocaleString('en-GB')} ${esc(x.error||'')}</p><button data-act="photo-open" data-id="${x.id}">Open saved files</button>${!x.details?`<button data-act="photo-read" data-id="${x.id}">Read photo (paid)</button>`:`<details><summary>Review extracted details</summary><pre>${esc(x.details.transcript)}</pre><form data-form="photo-review" data-id="${x.id}">${x.details.kind==='receipt'?Object.entries(x.details.receipt).map(([k,v])=>field(k,'receipt:'+k,v)).join(''):x.details.kind==='card'?Object.entries(x.details.contact).map(([k,v])=>field(k,'contact:'+k,v)).join(''):'<p>Whiteboard actions are editable in your to-do list. Unclear text remains in this transcript.</p>'}<button>Mark details reviewed</button></form></details>`}</article>`).join('')}`;
  }
  async function guard(fn){if(busy)return;busy=true;panel?.querySelectorAll('button').forEach(b=>b.disabled=true);try{say('Working…');return await fn();}finally{busy=false;if(panel){panel.querySelectorAll('button').forEach(b=>b.disabled=false);const empty=panel.querySelector('[data-form=trophy] button');if(empty&&!state.eligible.length)empty.disabled=true;}}}
  async function refresh(){state=await api('work-desk');draw();}
  function editPayload(form){const p=Object.fromEntries(new FormData(form)),sections={};for(const [k,v]of Object.entries(p))if(k.startsWith('section:'))sections[k.slice(8)]=v;return {...p,id:form.dataset.id,sections};}
  async function run(act,b){if(busy)return;if(act==='close')return close();if(act==='tab'){tab=b.dataset.tab;say('');draw();panel.querySelector('.wb-body').scrollTop=0;return;}if(act==='draft-close'){draft=null;draw();return;}if(act==='edit'){draft=state.proposals.find(p=>p.id===b.dataset.id);draw();return;}
    return guard(async()=>{const id=b.dataset.id;
      if(act==='folder'||act==='logo'){const s=await J.call('desk-'+act);if(s){state=s;if(act==='folder')answer=null;draw();}say('Ready.');}
      if(act==='export'){draft=await api('desk-edit',editPayload(b.closest('form')));const out=await api('desk-export',{id});await refresh();say((out.pdf?'PDF saved for review: ':'Editable proposal saved; PDF unavailable'+(out.pdfError?' ('+out.pdfError+')':'')+': ')+(out.pdf||out.html));await api('desk-open',{kind:'proposal',id});}
      if(act==='source'){await api('desk-open',{kind:'source',id});say('Source document opened.');}
      if(act==='result'){await api('desk-open',{kind:'trophy',id});say('Finished work opened.');}
      if(act==='restore'){await api('desk-restore',{id});await refresh();say('Removed from the wall. Finished files remain saved.');}
      if(act==='portfolio'){const f=await api('desk-portfolio');say('Portfolio saved locally: '+f);await api('desk-open',{kind:'portfolio'});}
      if(act==='photo-import'){const result=await J.call('desk-photo');await refresh();say(result||'No photo selected.');}
      if(act==='photo-open'){await api('photo-open',{id});say('Saved photo files opened.');}
      if(act==='photo-read'){await api('photo-read',{id});await refresh();say('Photo filed. Review its details below.');}
    });
  }
  async function submit(form){await guard(async()=>{const p=Object.fromEntries(new FormData(form)),kind=form.dataset.form;
    if(kind==='brand'){await api('desk-brand',p);await refresh();say('Branding saved.');}
    if(kind==='voices'){await api('save',{workDesk:{personalities:p.personalities==='on'}});await refresh();say('Voice personality preference saved.');}
    if(kind==='proposal'){draft=await api('desk-proposal',p);await refresh();say('Draft ready. Check each section and any missing details.');}
    if(kind==='edit'){draft=await api('desk-edit',editPayload(form));await refresh();say('Draft saved.');}
    if(kind==='files'){answer={...await api('desk-answer',{question:p.question}),question:p.question};draw();say('Source passages are shown below.');}
    if(kind==='trophy'){const [theme,suitId]=p.suit.split(':');await api('desk-retire',{...p,theme,suitId});await refresh();say('Project retired to the trophy wall.');}
    if(kind==='photos'){await api('save',{workDesk:{photoDrop:p.photoDrop==='on',photoAnalysis:p.photoAnalysis==='on',photoLimit:Number(p.photoLimit)}});await refresh();say('Photo preferences saved.');}
    if(kind==='photo-review'){const details={};for(const [k,v]of Object.entries(p)){const [group,key]=k.split(':');if(key)(details[group]||={})[key]=v;}await api('photo-review',{id:form.dataset.id,details});await refresh();say('Details marked reviewed.');}
  });}
  addEventListener('keydown',e=>{if(!panel)return;if(e.key==='Escape'){e.preventDefault();close();}if(e.key==='Tab'){const f=[...panel.querySelectorAll('button:not(:disabled),input,textarea,select,summary')].filter(x=>x.offsetParent!==null),a=f[0],b=f.at(-1);if(e.shiftKey&&document.activeElement===a){e.preventDefault();b?.focus();}else if(!e.shiftKey&&document.activeElement===b){e.preventDefault();a?.focus();}}});
  window.__jarvisWorkDesk={show,close};
}
